// One output item per invoice node across all fetched pages.
const invoices = [];
for (const page of $input.all()) {
  const nodes = page.json?.data?.invoices?.nodes ?? [];
  for (const invoice of nodes) {
    invoices.push({ json: invoice });
  }
}
return invoices;

// Runs once per invoice; a thrown error goes to the error output.
const invoice = $json;
const total = typeof invoice.total === 'string' ? invoice.total : '';
if (!/^\d+\.\d{2}$/.test(total)) {
  throw new Error(`invalid_total: ${invoice.id} has total ${JSON.stringify(invoice.total)}`);
}
// Integer string math: "450.50" -> "45050" -> 45050, no floating point.
const [units, cents] = total.split('.');
const totalCents = parseInt(units + cents, 10);
if (!Number.isSafeInteger(totalCents)) {
  throw new Error(`invalid_total: ${invoice.id} total is out of range`);
}
const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(invoice.issuedAt ?? ''));
if (!match) {
  throw new Error(`invalid_issued_at: ${invoice.id} has issuedAt ${JSON.stringify(invoice.issuedAt)}`);
}
// ISO 8601 week: shift to the Thursday of the same week, then count weeks.
const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
const weekday = date.getUTCDay() || 7;
date.setUTCDate(date.getUTCDate() + 4 - weekday);
const isoYear = date.getUTCFullYear();
const week = Math.ceil(((date - Date.UTC(isoYear, 0, 1)) / 86400000 + 1) / 7);
return {
  json: {
    id: invoice.id,
    client: invoice.client,
    status: invoice.status,
    total_cents: totalCents,
    issued_at: invoice.issuedAt,
    iso_week: `${isoYear}-W${String(week).padStart(2, '0')}`,
  },
};

// Weekly KPIs over all valid invoices, in cents.
const weeks = {};
for (const { json: invoice } of $input.all()) {
  const week = (weeks[invoice.iso_week] ??= {
    iso_week: invoice.iso_week,
    revenue_paid_cents: 0,
    invoices_paid: 0,
    invoices_open: 0,
  });
  if (invoice.status === 'paid') {
    week.revenue_paid_cents += invoice.total_cents;
    week.invoices_paid += 1;
  } else if (invoice.status === 'awaiting_payment') {
    week.invoices_open += 1;
  }
}
return Object.keys(weeks).sort().map((key) => {
  const week = weeks[key];
  week.avg_paid_cents = week.invoices_paid
    ? Math.floor(week.revenue_paid_cents / week.invoices_paid)
    : 0;
  return { json: week };
});

// Items from the Validate & Transform error output (input fields + error).
return $input.all().map((item) => ({
  json: {
    stage: 'validate',
    id: item.json.id,
    total: item.json.total,
    reason: item.json.error,
  },
}));

// HTTP error output retains the source item and attaches error metadata.
return $input.all().map((item, index) => {
  const error = item.json.error;
  const original = item.json.id ? item.json : $('Validate & Transform').itemMatching(index).json;
  const message = typeof error === 'string' ? error : String(error?.message ?? error?.description ?? 'upsert_failed');
  const statusInMessage = /\b([45]\d{2})\b/.exec(message);
  return { json: {
    stage: 'upsert',
    id: item.json.id ?? original.id,
    status: error?.statusCode ?? error?.httpCode ?? error?.status ?? item.json.statusCode ?? (statusInMessage ? Number(statusInMessage[1]) : null),
    message: message,
  } };
});
